ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_guarded_cancellation_pair_check" CHECK (("subscriptions"."guarded_cancellation_token" is null and "subscriptions"."guarded_cancellation_started_at" is null and "subscriptions"."guarded_cancellation_requested_by_user_id" is null) or ("subscriptions"."guarded_cancellation_token" is not null and "subscriptions"."guarded_cancellation_started_at" is not null));